package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MvcResult;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;

class TmpProbeTest extends AcceptanceBase {

	@Test
	void malformedJsonProbe() throws Exception {
		MvcResult r = mvc.perform(post("/api/owners")
				.contentType(MediaType.APPLICATION_JSON)
				.content("{ this is not json "))
				.andReturn();
		System.out.println("PROBE_STATUS=" + r.getResponse().getStatus());
		System.out.println("PROBE_CT=" + r.getResponse().getContentType());
		System.out.println("PROBE_BODY=" + r.getResponse().getContentAsString());
	}
}
